module parallel2serial (
    input wire clk,
    input wire rst_n,
    input wire [3:0]d,
    output wire valid_out,
    output wire dout
);

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin

        cnt <= 3'd0;
    end else begin

        if (cnt == 3'd3) begin
            data <= d;
            cnt <= 3'd0;
            valid <= 1'b1;
        end else begin

            cnt <= cnt + 3'd1;
            valid <= 1'b0;
            data <= {data[2:0], data[3]};
        end
    end
end

assign dout = data[3];

assign valid_out = valid;

reg [2:0] cnt;

reg valid;

reg [3:0] data;
endmodule
